# area: self_classmethods
# hypothesis: Self returned by a fluent builder and by a classmethod alternative constructor should bind to the receiver subclass HtmlBuilder, not to Builder.
from typing import Self, reveal_type


class Builder:
    def __init__(self) -> None:
        self.parts: list[str] = []

    def add(self, part: str) -> Self:
        self.parts.append(part)
        return self

    @classmethod
    def start(cls, first: str) -> Self:
        return cls().add(first)

    @property
    def count(self) -> int:
        return len(self.parts)


class HtmlBuilder(Builder):
    def close(self) -> Self:
        self.parts.append('</>')
        return self


page = HtmlBuilder.start('<html>').add('<body>').close()
reveal_type(page)
reveal_type(HtmlBuilder.start)
reveal_type(page.add('x').count)
reveal_type(Builder.start('x'))
